import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import {
  createTestContext,
  recordEvent,
  replayEvents,
  getDatabase,
  insertNode,
  type HiveContext,
  type Node,
} from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}
async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('incremental replay must not invent conflicts absent from a full rebuild', () => {
  it('replays two chained status transitions as a clean fast-forward, creating no conflict ref', async () => {
    const { ctx } = await bootstrap();
    const db = getDatabase(ctx);

    // 1. Append an 'add' event for node G to the log ONLY. recordEvent materialises
    //    nothing for 'add', so the node is absent from the db while we record status
    //    (which keeps recordEvent from writing the transitions to the db directly).
    const gId = await recordEvent(
      ctx,
      { type: 'add', nodeType: 'decision', content: 'G', confidence: 90 },
      branch,
    );

    // Watermark now sits at the add commit — exactly the state a collaborator would be
    // synced to just before two status pushes arrive over git.
    const addHash = (
      db.prepare(`SELECT last_synced_git_hash FROM sync_state WHERE branch = ?`).get(branch) as {
        last_synced_git_hash: string;
      }
    ).last_synced_git_hash;

    // 2. Two chained status transitions. Because G is not yet in the db, recordEvent
    //    writes them to git ONLY; each commit body carries a correct `parents` field
    //    (derived from the git log alone), so the log is unambiguous: completed is a
    //    descendant of active.
    await recordEvent(ctx, { type: 'status', nodeId: gId, status: 'active' }, branch);
    await recordEvent(ctx, { type: 'status', nodeId: gId, status: 'completed' }, branch);

    // 3. Now the node exists in the db (as it would after the 'add' had been replayed),
    //    but the two status commits have not yet been applied to the db.
    const now = new Date().toISOString();
    const node: Node = {
      change_id: gId,
      branch,
      node_type: 'decision',
      title: 'G',
      status: 'pending',
      created_at: now,
      updated_at: now,
    };
    insertNode(db, node);

    // 4. Rewind the watermark to just before the two status pushes, forcing the
    //    INCREMENTAL replay path (getCommitsSince) instead of a full rebuild.
    db.prepare(`UPDATE sync_state SET last_synced_git_hash = ? WHERE branch = ?`).run(addHash, branch);

    await replayEvents(ctx, branch, false);

    // A full rebuild fast-forwards these two transitions cleanly. The incremental path
    // must yield the SAME database — no synthetic `${branch}:conflict:<sha7>` ref.
    const refs = db
      .prepare(`SELECT branch FROM state_refs WHERE node_id = ? AND property = 'status'`)
      .all(gId) as { branch: string }[];
    const conflictRefs = refs.filter((r) => r.branch.startsWith(`${branch}:conflict:`));

    expect(conflictRefs.length).toBe(0);
  });
});
